<?php
namespace App\Models; use App\Models\Concerns\InvalidatesClients; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany}; class Client extends Model { use HasFactory,InvalidatesClients; protected $fillable=['name','slug','client_type','short_description','logo_path','logo_alt','website_url','country_code','industry_id','status','is_featured','display_order','published_at','scheduled_for','archived_at','meta_title','meta_description','canonical_url','robots_index','robots_follow','created_by','updated_by']; protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function industry():BelongsTo{return $this->belongsTo(Industry::class);} public function testimonials():HasMany{return $this->hasMany(Testimonial::class);} public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);} public function navigationItems():HasMany{return $this->hasMany(NavigationItem::class);} public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'client_solution_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'client_product_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedCapabilities():BelongsToMany{return $this->belongsToMany(Capability::class,'client_capability_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'client_page_relations')->withPivot('display_order')->orderByPivot('display_order');} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
